import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CCXDMzJr.js";const m=JSON.parse('{"title":"申请注册","description":"","frontmatter":{},"headers":[],"relativePath":"connect/request.md","filePath":"connect/request.md"}'),n={name:"connect/request.md"};function l(i,e,c,d,p,s){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="申请注册" tabindex="-1">申请注册 <a class="header-anchor" href="#申请注册" aria-label="Permalink to &quot;申请注册&quot;">​</a></h1><p>为了保证 DN11 的资源的可用性，我们需要对资源进行统一管理。DN11 的 ASN、网段等资源统一在 <a href="https://github.com/dn-11/registry" target="_blank" rel="noreferrer">dn11-registry</a> 进行登记和管理。在接入 DN11 前，你需要提交一个 Pull Request 用于向 DN11 请求分配网络资源。</p><h2 id="选择一个-asn" tabindex="-1">选择一个 ASN <a class="header-anchor" href="#选择一个-asn" aria-label="Permalink to &quot;选择一个 ASN&quot;">​</a></h2><p>ASN 是一个 uint32 数字，但我们规定 4211110000-4211119999 这个范围是 DN11 目前开发申请的 ASN 范围。</p><p>你可以在 <a href="https://github.com/dn-11/metadata/blob/main/README.md" target="_blank" rel="noreferrer">DN11 信息表</a> 查看到目前所有已经被申请的 ASN，选择一个在开放申请范围内且不重复的 ASN 即可。</p><h2 id="选择一个网段" tabindex="-1">选择一个网段 <a class="header-anchor" href="#选择一个网段" aria-label="Permalink to &quot;选择一个网段&quot;">​</a></h2><p>对于新成员，DN11 <strong>强制</strong> 使用 <a href="https://github.com/dn-11/metadata/blob/main/README.md" target="_blank" rel="noreferrer">DN11 信息表</a> 中展示的 “下一个建议使用的网段”。</p><h2 id="成员注册" tabindex="-1">成员注册 <a class="header-anchor" href="#成员注册" aria-label="Permalink to &quot;成员注册&quot;">​</a></h2><p>请在 <a href="https://github.com/dn-11/registry" target="_blank" rel="noreferrer">dn11-registry</a> 的 <code>as</code> 目录中创建一个 YAML 文件，文件名为 <code>&lt;your-asn&gt;.yml</code> ，然后以 <a href="https://github.com/dn-11/registry/blob/main/as/example.minimal.yml" target="_blank" rel="noreferrer"><code>example.minimal.yml</code> (推荐的最小配置)</a> 为模板填写。填写完成后提交一个 PR，根据 Checker 回复修改您的配置，然后等待管理员合并即可。</p><ul><li><p><code>ASN</code></p><p>填写在上文时选择的 ASN。</p></li><li><p><code>name</code></p><p>您的名字 / ID。</p></li><li><p><code>contact</code></p><p>联系方式，如 QQ / Email，</p><p>如使用 QQ 号等纯数字，请使用引号包裹，确保该项的值为字符串。</p></li><li><p><code>ip</code></p><p>填写在上文时找到的 “下一个建议使用的网段”。</p></li></ul>',10)])])}const u=a(n,[["render",l]]);export{m as __pageData,u as default};
